// Styling for the global footer.
//
// The photograph here is atmosphere, not subject, so the overlay is heavy —
// around 0.93 — and the image was chosen for structural contrast (window
// grids, balcony rhythm) that survives being almost blacked out.
//
// The giant outlined wordmark reuses the section-title technique at a much
// lower opacity, and sits behind the bottom bar so it never competes with a
// link. It is clipped by the footer rather than allowed to widen the page.

import template1 from "./template-1";

export type FooterTemplate = {
  css: string;
  rootClass: string;
  layout: typeof template1.layout;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-footer {
  position: relative;
  background: ${color.base};
  color: ${color.link};
  overflow: hidden;
  isolation: isolate;
}

/* Gold line marking the seam with the CTA above. */
.kr-footer::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  z-index: 4;
  width: ${layout.topAccentWidth};
  height: ${layout.topAccentHeight}px;
  background: ${color.topAccent};
}

.kr-footer__media { position: absolute; inset: 0; z-index: 0; }
.kr-footer__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.kr-footer__scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: ${color.scrim};
  pointer-events: none;
}

/* ── giant outlined wordmark ──────────────────────────── */
.kr-footer__ghost {
  container-type: inline-size;
  position: absolute;
  left: 0;
  right: 0;
  bottom: ${spacing.ghostTop}px;
  z-index: 1;
  display: flex;
  justify-content: center;
  pointer-events: none;
  user-select: none;
}
.kr-footer__ghost span {
  font-family: ${typography.ghostFamily};
  /* Same fit-to-width guard as the section headings. */
  font-size: min(${layout.ghostSize}, calc(100cqi / (var(--kr-footer-ghost-chars, 12) * 0.62)));
  font-weight: ${typography.ghostWeight};
  line-height: .8;
  letter-spacing: ${typography.ghostTracking};
  text-transform: uppercase;
  white-space: nowrap;
  color: transparent;
  -webkit-text-stroke: ${layout.ghostStrokeWidth}px ${color.ghostStroke};
  opacity: ${color.ghostOpacity};
}

.kr-footer__inner {
  position: relative;
  z-index: 2;
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: ${spacing.sectionTop}px ${spacing.gutter}px 0;
}

/* ── columns ──────────────────────────────────────────── */
.kr-footer__grid {
  display: grid;
  grid-template-columns: ${layout.brandColumn} repeat(3, ${layout.linkColumn});
  gap: ${spacing.columnGap}px;
  padding-bottom: 64px;
}

.kr-footer__wordmark {
  display: inline-block;
  margin: 0 0 ${spacing.wordmarkGap}px;
  color: ${color.wordmark};
  font-family: ${typography.wordmarkFamily};
  font-size: ${typography.wordmarkSize}px;
  font-weight: ${typography.wordmarkWeight};
  letter-spacing: ${typography.wordmarkTracking};
  line-height: 1;
  text-decoration: none;
}
.kr-footer__wordmark-accent { color: ${color.wordmarkAccent}; }
.kr-footer__wordmark:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 4px; }

.kr-footer__blurb {
  margin: 0;
  max-width: ${spacing.blurbMaxWidth};
  color: ${color.blurb};
  font-family: ${typography.blurbFamily};
  font-size: ${typography.blurbSize}px;
  font-weight: ${typography.blurbWeight};
  line-height: ${typography.blurbLeading};
}

.kr-footer__column-title {
  margin: 0 0 ${spacing.columnTitleGap}px;
  color: ${color.columnTitle};
  font-family: ${typography.columnTitleFamily};
  font-size: ${typography.columnTitleSize}px;
  font-weight: ${typography.columnTitleWeight};
  letter-spacing: ${typography.columnTitleTracking};
  text-transform: uppercase;
}

.kr-footer__links { margin: 0; padding: 0; list-style: none; }
.kr-footer__links li + li { margin-top: ${spacing.linkGap}px; }

/* Gold underline wiping in from the left. */
.kr-footer__link {
  position: relative;
  display: inline-block;
  color: ${color.link};
  font-family: ${typography.linkFamily};
  font-size: ${typography.linkSize}px;
  font-weight: ${typography.linkWeight};
  text-decoration: none;
  transition: color ${timing.link}ms ${ease};
}
.kr-footer__link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -3px;
  height: 1px;
  background: ${color.linkRule};
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform ${timing.link}ms ${ease};
}
.kr-footer__link:hover { color: ${color.linkHover}; }
.kr-footer__link:hover::after { transform: scaleX(1); }
.kr-footer__link:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── contact ──────────────────────────────────────────── */
.kr-footer__contact { margin: 0; padding: 0; list-style: none; }
.kr-footer__contact li + li { margin-top: ${spacing.contactGap}px; }
.kr-footer__contact-row {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  color: ${color.contactText};
  font-family: ${typography.contactFamily};
  font-size: ${typography.contactSize}px;
  font-weight: ${typography.contactWeight};
  line-height: 1.5;
  text-decoration: none;
  transition: color ${timing.link}ms ${ease};
}
a.kr-footer__contact-row:hover { color: ${color.linkHover}; }
a.kr-footer__contact-row:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }
.kr-footer__contact-icon {
  display: inline-flex;
  flex-shrink: 0;
  margin-top: 2px;
  color: ${color.contactIcon};
}

/* ── bottom bar ───────────────────────────────────────── */
.kr-footer__bottom {
  position: relative;
  z-index: 2;
  border-top: 1px solid ${color.divider};
  padding: ${spacing.bottomPaddingY}px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}
.kr-footer__copyright {
  margin: 0;
  color: ${color.legal};
  font-family: ${typography.legalFamily};
  font-size: ${typography.legalSize}px;
  font-weight: ${typography.legalWeight};
}
.kr-footer__legal {
  display: flex;
  flex-wrap: wrap;
  gap: ${spacing.legalGap}px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-footer__legal a {
  color: ${color.legal};
  font-family: ${typography.legalFamily};
  font-size: ${typography.legalSize}px;
  text-decoration: none;
  transition: color ${timing.link}ms ${ease};
}
.kr-footer__legal a:hover { color: ${color.legalHover}; }
.kr-footer__legal a:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── back to top ──────────────────────────────────────── */
.kr-totop {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 800;
  width: ${layout.toTopSize}px;
  height: ${layout.toTopSize}px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid ${color.toTopBorder};
  border-radius: 2px;
  background: rgba(20, 23, 26, .82);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  color: ${color.toTopIcon};
  cursor: pointer;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition:
    opacity ${timing.toTop}ms ${ease},
    transform ${timing.toTop}ms ${ease},
    background-color ${timing.toTop}ms ${ease},
    color ${timing.toTop}ms ${ease},
    border-color ${timing.toTop}ms ${ease},
    visibility 0s linear ${timing.toTop}ms;
}
.kr-totop--shown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition-delay: 0s;
}
.kr-totop:hover {
  background: ${color.toTopHoverBackground};
  border-color: ${color.toTopHoverBackground};
  color: ${color.toTopHoverIcon};
}
.kr-totop:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── responsive ───────────────────────────────────────── */
@media (max-width: ${layout.stackBelow}px) {
  .kr-footer__inner {
    padding: ${spacing.sectionTopCompact}px ${spacing.gutterCompact}px 0;
  }
  /* Four microscopic columns help nobody; brand spans, links pair up. */
  .kr-footer__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: ${spacing.columnGapCompact}px;
    padding-bottom: 48px;
  }
  .kr-footer__brand { grid-column: 1 / -1; }
  .kr-footer__col--contact { grid-column: 1 / -1; }
  .kr-footer__bottom { justify-content: flex-start; }
}

@media (max-width: 520px) {
  .kr-footer__grid { grid-template-columns: minmax(0, 1fr); }
  .kr-totop { right: 16px; bottom: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-footer__link,
  .kr-footer__link::after,
  .kr-footer__contact-row,
  .kr-totop {
    transition: none;
  }
}
`;

const template: FooterTemplate = {
  css,
  rootClass: "kr-footer",
  layout,
};

export default template;
