import { useSyncExternalStore } from "react";
import { createLiveStore } from "../../modules/shared/liveStore";
import { catalogueRecords } from "../../modules/property/catalogueRules";
import { loadPropertiesDocument } from "../../modules/supabase/propertiesSupabase";
import { usingSupabase } from "../../modules/supabase/enabled";
import { catalogue } from "./catalogue";
import { properties as samples } from "./property-data";

const store = createLiveStore(catalogue, async () => {
  const result = await loadPropertiesDocument();
  if (!result.ok) throw new Error(result.error.message);
  return catalogueRecords(result.data, samples);
});
const bundled = { data: catalogue, ready: true, error: null };
const noSubscribe = () => () => {};
const getBundled = () => bundled;

/** Static HTML for first paint, then the latest public Supabase document. */
export function useCatalogue() {
  const enabled = usingSupabase();
  return useSyncExternalStore(
    enabled ? store.subscribe : noSubscribe,
    enabled ? store.getSnapshot : getBundled,
    enabled ? store.getServerSnapshot : getBundled
  );
}
