import React, { useEffect, useRef, useState } from "react";
import { Link } from "gatsby";

import type { HeaderLabels, HeaderTemplate } from "../../templates/header/default-template";
import type { NavItem, TopBarItem } from "./types";
import useHeaderScroll from "./useHeaderScroll";

export type SiteHeaderProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: HeaderTemplate;
  /** Wordmark text; the trailing accent character is rendered in gold. */
  wordmark: string;
  wordmarkAccent?: string;
  nav: NavItem[];
  cta: NavItem;
  /** Left-hand top-bar group. */
  topBarLeft: TopBarItem[];
  /** Right-hand top-bar group. */
  topBarRight: TopBarItem[];
  /**
   * "overlay" starts transparent over hero photography and turns solid on
   * scroll — the homepage. "light" is solid from the first paint, for interior
   * pages whose content starts against a pale background.
   */
  variant?: "overlay" | "light";
  /** Master switch. */
  enabled?: boolean;
  /** Render the top bar above the main row. */
  showTopBar?: boolean;
  labels?: Partial<HeaderLabels>;
};

const ICON_SIZE = 13;

/** One top-bar entry: gold glyph, then label. A link only when it has an href. */
function TopBarEntry({ item }: { item: TopBarItem }) {
  const Icon = item.icon;

  const body = (
    <>
      {Icon ? (
        <span className="kr-topbar__icon" aria-hidden="true">
          <Icon size={ICON_SIZE} />
        </span>
      ) : null}
      {item.label}
    </>
  );

  const className = `kr-topbar__item${item.optional ? " kr-topbar__item--optional" : ""}`;

  return item.href ? (
    <a className={className} href={item.href}>
      {body}
    </a>
  ) : (
    <span className={className}>{body}</span>
  );
}

/** Items joined by hairline dividers. */
function TopBarGroup({ items }: { items: TopBarItem[] }) {
  return (
    <div className="kr-topbar__group">
      {items.map((item, index) => (
        <React.Fragment key={item.label}>
          {index > 0 ? (
            <span className="kr-topbar__divider" aria-hidden="true" />
          ) : null}
          <TopBarEntry item={item} />
        </React.Fragment>
      ))}
    </div>
  );
}

/**
 * The header mechanism: scroll state, drawer state and markup. Holds no
 * colours, sizes or copy — those arrive via `template` and props, so a
 * restyle is a template swap and a reword is a primitive edit.
 */
export default function SiteHeader({
  template,
  wordmark,
  wordmarkAccent = "",
  nav,
  cta,
  topBarLeft,
  topBarRight,
  variant = "overlay",
  enabled = true,
  showTopBar = true,
  labels: labelOverrides,
}: SiteHeaderProps) {
  const labels = { ...template.labels, ...labelOverrides };
  const scrolled = useHeaderScroll(template.timing.scrollThreshold);
  /* Geometry always follows scroll; colour additionally follows the variant. */
  const solid = variant === "light" || scrolled;
  const [drawerOpen, setDrawerOpen] = useState(false);

  const burgerRef = useRef<HTMLButtonElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);

  // Escape closes the drawer, and the page behind it must not scroll while
  // a full-screen panel is covering it.
  useEffect(() => {
    if (!drawerOpen) return;

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setDrawerOpen(false);
    };

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    document.addEventListener("keydown", onKeyDown);
    closeRef.current?.focus();

    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [drawerOpen]);

  if (!enabled) return null;

  const root = template.rootClass;
  const mark = (accentClass: string) => (
    <>
      {wordmark}
      {wordmarkAccent ? (
        <span className={accentClass}>{wordmarkAccent}</span>
      ) : null}
    </>
  );

  const closeDrawer = () => {
    setDrawerOpen(false);
    burgerRef.current?.focus();
  };

  return (
    <>
      <style>{template.css}</style>

      <header
        className={[
          root,
          solid ? `${root}--solid` : "",
          scrolled ? `${root}--scrolled` : "",
        ]
          .filter(Boolean)
          .join(" ")}
      >
        <div className={`${root}__scrim`} aria-hidden="true" />

        {showTopBar ? (
          <div className="kr-topbar">
            <div className="kr-topbar__inner">
              <TopBarGroup items={topBarLeft} />
              <TopBarGroup items={topBarRight} />
            </div>
          </div>
        ) : null}

        <div className={`${root}__bar`}>
          <div className={`${root}__inner`}>
            <Link to="/" className={`${root}__logo`} aria-label={labels.homeLabel}>
              {mark(`${root}__logo-accent`)}
            </Link>

            <nav className={`${root}__nav`} aria-label={labels.navLabel}>
              {nav.map((item) => (
                <Link
                  key={item.to}
                  to={item.to}
                  className={`${root}__link`}
                  activeClassName={`${root}__link--active`}
                >
                  {item.label}
                </Link>
              ))}
            </nav>

            <Link to={cta.to} className={`kr-btn kr-btn--gold ${root}__cta`}>
              {cta.label}
            </Link>

            <button
              ref={burgerRef}
              type="button"
              className={`${root}__burger`}
              aria-label={labels.openMenu}
              aria-expanded={drawerOpen}
              aria-controls="kr-drawer"
              onClick={() => setDrawerOpen(true)}
            >
              <span />
              <span />
              <span />
            </button>
          </div>
        </div>
      </header>

      <div
        id="kr-drawer"
        className={`kr-drawer${drawerOpen ? " kr-drawer--open" : ""}`}
        aria-hidden={!drawerOpen}
      >
        <div className="kr-drawer__head">
          <Link to="/" className="kr-drawer__logo" onClick={closeDrawer}>
            {mark("kr-drawer__logo-accent")}
          </Link>

          <button
            ref={closeRef}
            type="button"
            className="kr-drawer__close"
            aria-label={labels.closeMenu}
            onClick={closeDrawer}
          >
            <span />
            <span />
          </button>
        </div>

        <nav className="kr-drawer__nav" aria-label={labels.navLabel}>
          {nav.map((item) => (
            <Link
              key={item.to}
              to={item.to}
              className="kr-drawer__link"
              activeClassName="kr-drawer__link--active"
              onClick={closeDrawer}
            >
              {item.label}
            </Link>
          ))}
        </nav>

        <Link
          to={cta.to}
          className="kr-btn kr-btn--gold kr-drawer__cta"
          onClick={closeDrawer}
        >
          {cta.label}
        </Link>

        <div className="kr-drawer__meta">
          {[...topBarLeft, ...topBarRight].map((item) => {
            const Icon = item.icon;
            const body = (
              <>
                {Icon ? (
                  <span className="kr-topbar__icon" aria-hidden="true">
                    <Icon size={ICON_SIZE} />
                  </span>
                ) : null}
                {item.label}
              </>
            );

            return item.href ? (
              <a key={item.label} className="kr-drawer__meta-item" href={item.href}>
                {body}
              </a>
            ) : (
              <span key={item.label} className="kr-drawer__meta-item">
                {body}
              </span>
            );
          })}
        </div>
      </div>
    </>
  );
}
