/** Shared browser polling: one request per resource, regardless of consumer count. */
export const LIVE_REFRESH_MS = 5_000;

export type LiveSnapshot<T> = { data: T; ready: boolean; error: string | null };

export function createLiveStore<T>(initial: T, load: () => Promise<T>) {
  const server: LiveSnapshot<T> = { data: initial, ready: false, error: null };
  let snapshot = server;
  const listeners = new Set<() => void>();
  let stop: (() => void) | undefined;

  function start() {
    let active = true;
    let pending = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const refresh = async () => {
      if (!active || pending) return;
      clearTimeout(timer);
      if (document.visibilityState !== "hidden") {
        pending = true;
        try {
          const data = await load();
          if (active) {
            // Keep object identity when unchanged, preserving form/gallery state.
            const same = JSON.stringify(data) === JSON.stringify(snapshot.data);
            snapshot = { data: same ? snapshot.data : data, ready: true, error: null };
          }
        } catch {
          if (active) snapshot = {
            ...snapshot, ready: true,
            error: "We couldn't refresh the latest information. Please check your connection. We'll try again automatically.",
          };
        } finally {
          pending = false;
        }
        if (active) listeners.forEach((listener) => listener());
      }
      if (active) timer = setTimeout(refresh, LIVE_REFRESH_MS);
    };
    window.addEventListener("focus", refresh);
    window.addEventListener("online", refresh);
    window.addEventListener("pageshow", refresh);
    document.addEventListener("visibilitychange", refresh);
    void refresh();
    return () => {
      active = false;
      clearTimeout(timer);
      window.removeEventListener("focus", refresh);
      window.removeEventListener("online", refresh);
      window.removeEventListener("pageshow", refresh);
      document.removeEventListener("visibilitychange", refresh);
    };
  }

  return {
    getSnapshot: () => snapshot,
    getServerSnapshot: () => server,
    subscribe(listener: () => void) {
      listeners.add(listener);
      if (!stop && typeof window !== "undefined") stop = start();
      return () => {
        listeners.delete(listener);
        if (!listeners.size) { stop?.(); stop = undefined; }
      };
    },
  };
}
