import React from "react";
import { Link } from "gatsby";

import type { FooterTemplate } from "../../templates/footer/default-template";
import BackToTop from "./BackToTop";
import type { FooterContent } from "./types";

export type FooterProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: FooterTemplate;
  content: FooterContent;
  /** Rendered as "© {year} {owner}. All rights reserved." */
  owner: string;
  backToTopLabel?: string;
  enabled?: boolean;
};

/**
 * The global site footer.
 *
 * One footer for every page — the property page and the rest reuse this, never
 * a copy. Everything visible comes from `content`, so the CMS can eventually
 * own the links and contact details without touching this file.
 */
export default function Footer({
  template,
  content,
  owner,
  backToTopLabel = "Back to top",
  enabled = true,
}: FooterProps) {
  if (!enabled) return null;

  const root = template.rootClass;
  /* Computed at render, never hard-coded — a stale year is a small thing that
     makes a site look abandoned. */
  const year = new Date().getFullYear();

  return (
    <>
      <footer className={root}>
        <style>{template.css}</style>

        <div className={`${root}__media`}>
          <img
            className={`${root}__image`}
            src={content.backdrop.src}
            srcSet={content.backdrop.srcSet}
            sizes={content.backdrop.srcSet ? "100vw" : undefined}
            alt={content.backdrop.alt}
            style={
              content.backdrop.position
                ? { objectPosition: content.backdrop.position }
                : undefined
            }
            /* Not lazy: the visitor arrives here having scrolled the whole
               page, and a blank dark rectangle at the end reads as broken. */
            loading="eager"
            decoding="async"
          />
        </div>
        <div className={`${root}__scrim`} aria-hidden="true" />

        <div
          className={`${root}__ghost`}
          aria-hidden="true"
          style={{ ["--kr-footer-ghost-chars"]: String(content.ghostText.length) } as React.CSSProperties}
        >
          <span>{content.ghostText}</span>
        </div>

        <div className={`${root}__inner`}>
          <div className={`${root}__grid`}>
            <div className={`${root}__brand`}>
              <Link to="/" className={`${root}__wordmark`}>
                {content.wordmark}
                {content.wordmarkAccent ? (
                  <span className={`${root}__wordmark-accent`}>
                    {content.wordmarkAccent}
                  </span>
                ) : null}
              </Link>
              <p className={`${root}__blurb`}>{content.blurb}</p>
            </div>

            {content.columns.map((column) => (
              <nav key={column.title} className={`${root}__col`} aria-label={column.title}>
                <p className={`${root}__column-title`}>{column.title}</p>
                <ul className={`${root}__links`}>
                  {column.links.map((link) => (
                    <li key={link.to + link.label}>
                      <Link className={`${root}__link`} to={link.to}>
                        {link.label}
                      </Link>
                    </li>
                  ))}
                </ul>
              </nav>
            ))}

            <div className={`${root}__col ${root}__col--contact`}>
              <p className={`${root}__column-title`}>{content.contact.title}</p>
              <ul className={`${root}__contact`}>
                {content.contact.items.map((item) => {
                  const Icon = item.icon;
                  const body = (
                    <>
                      <span className={`${root}__contact-icon`} aria-hidden="true">
                        <Icon size={15} strokeWidth={1.5} />
                      </span>
                      <span>{item.label}</span>
                    </>
                  );

                  return (
                    <li key={item.label}>
                      {item.href ? (
                        <a className={`${root}__contact-row`} href={item.href}>
                          {body}
                        </a>
                      ) : (
                        <span className={`${root}__contact-row`}>{body}</span>
                      )}
                    </li>
                  );
                })}
              </ul>
            </div>
          </div>

          <div className={`${root}__bottom`}>
            <p className={`${root}__copyright`}>
              © {year} {owner}. All rights reserved.
            </p>

            {content.legal.length ? (
              <ul className={`${root}__legal`}>
                {content.legal.map((item) => (
                  <li key={item.to}>
                    <Link to={item.to}>{item.label}</Link>
                  </li>
                ))}
              </ul>
            ) : null}
          </div>
        </div>
      </footer>

      <BackToTop after={template.layout.toTopAfter} label={backToTopLabel} />
    </>
  );
}
