import React from "react";
import { FiClock, FiMail, FiMapPin, FiPhone } from "react-icons/fi";

import template from "../../config/header--template";
import {
  EMAIL,
  EMAIL_HREF,
  HOURS,
  LOCATION,
  PHONE_DISPLAY,
  PHONE_HREF,
} from "../../config/profile--contact";
import SiteHeader from "../../modules/header/SiteHeader";
import type { NavItem, TopBarItem } from "../../modules/header/types";
import headerEnabled from "../../toggles/header";
import topBarEnabled from "../../toggles/header--top-bar";

const nav: NavItem[] = [
  { label: "Home", to: "/" },
  { label: "Properties", to: "/properties" },
  { label: "About Us", to: "/about" },
  { label: "Contact", to: "/contact" },
];

const cta: NavItem = { label: "Apply Now", to: "/apply" };

const topBarLeft: TopBarItem[] = [
  { label: PHONE_DISPLAY, href: PHONE_HREF, icon: FiPhone },
  { label: LOCATION, icon: FiMapPin, optional: true },
];

const topBarRight: TopBarItem[] = [
  { label: HOURS, icon: FiClock, optional: true },
  { label: EMAIL, href: EMAIL_HREF, icon: FiMail },
];

/**
 * The site header, configured.
 *
 * Template supplies structure, style and colour; this file supplies the
 * navigation, the call to action and the top-bar content. Restyle via
 * config/header--template.ts; change the menu here.
 *
 * Location and hours are marked optional: they are the first things dropped
 * as the viewport narrows, so phone and email survive longest.
 */
export type HeaderXProps = {
  /** "overlay" over hero photography, "light" for interior pages. */
  variant?: "overlay" | "light";
};

export default function HeaderX({ variant = "overlay" }: HeaderXProps) {
  return (
    <SiteHeader
      template={template}
      variant={variant}
      enabled={headerEnabled}
      showTopBar={topBarEnabled}
      wordmark="Kelley Road"
      wordmarkAccent="."
      nav={nav}
      cta={cta}
      topBarLeft={topBarLeft}
      topBarRight={topBarRight}
    />
  );
}
